package com.rustybank.legacy;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class MoneyUtil {

    public static long parse(String amount) {
        if (amount == null) {
            throw new IllegalArgumentException("INVALID AMOUNT");
        }
        BigDecimal bd = new BigDecimal(amount.trim());
        if (bd.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
        }
        // Convert to cents, ensuring exact conversion (no more than two decimal places)
        try {
            return bd.multiply(BigDecimal.valueOf(100))
                    .setScale(0, RoundingMode.UNNECESSARY)
                    .longValueExact();
        } catch (ArithmeticException e) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
        }
    }

    public static String format(long cents) {
        long whole = cents / 100;
        long frac = cents % 100;
        // Ensure fraction is non-negative (cents is always non-negative)
        if (frac < 0) {
            frac = -frac;
        }
        StringBuilder sb = new StringBuilder();
        sb.append(whole).append('.');
        if (frac < 10) {
            sb.append('0');
        }
        sb.append(frac);
        return sb.toString();
    }
}

