import java.util.List;

public class LegacyTellerTerminal implements TellerTerminal {

    private final AccountStore store = new AccountStore();

    @Override
    public void openAccount(String accountId) {
        store.add(accountId);
    }

    @Override
    public void deposit(String accountId, String amount) {
        Account a = store.find(accountId);
        long cents = MoneyUtil.parse(amount);
        a.setBalanceCents(a.getBalanceCents() + cents);
    }

    @Override
    public void withdraw(String accountId, String amount) {
        Account a = store.find(accountId);
        long cents = MoneyUtil.parse(amount);
        if (cents > a.getBalanceCents()) {
            throw new IllegalStateException("INSUFFICIENT FUNDS");
        }
        a.setBalanceCents(a.getBalanceCents() - cents);
    }

    @Override
    public String balance(String accountId) {
        Account a = store.find(accountId);
        return MoneyUtil.format(a.getBalanceCents());
    }

    @Override
    public String postMonthlyInterest(String accountId, String annualRatePercent) {
        Account a = store.find(accountId);
        long balanceCents = a.getBalanceCents();

        // Parse rate as a BigDecimal (percent)
        BigDecimal rate = new BigDecimal(annualRatePercent.trim());
        if (rate.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("INVALID RATE: " + annualRatePercent);
        }

        // Compute interest in cents: balanceCents * rate / (100 * 12), rounded half-up
        BigDecimal divisor = BigDecimal.valueOf(100 * 12); // 1200
        BigDecimal interestBD = BigDecimal.valueOf(balanceCents)
                .multiply(rate)
                .divide(divisor, 0, RoundingMode.HALF_UP);
        long interestCents = interestBD.longValueExact();

        a.setBalanceCents(balanceCents + interestCents);
        return MoneyUtil.format(interestCents);
    }

    @Override
    public List<String> splitPayment(String fromAccountId, String amount, List<String> payeeIds) {
        Account from = store.find(fromAccountId);
        long totalCents = MoneyUtil.parse(amount);

        if (payeeIds == null || payeeIds.isEmpty()) {
            throw new IllegalArgumentException("NO PAYEES");
        }

        List<Account> payees = new ArrayList<>();
        for (String pid : payeeIds) {
            payees.add(store.find(pid));
        }

        if (totalCents > from.getBalanceCents()) {
            throw new IllegalStateException("INSUFFICIENT FUNDS");
        }

        int numPayees = payees.size();
        long base = totalCents / numPayees;
        long remainder = totalCents % numPayees;

        List<String> shares = new ArrayList<>();
        for (int i = 0; i < numPayees; i++) {
            long shareCents = base + (i < remainder ? 1 : 0);
            Account p = payees.get(i);
            p.setBalanceCents(p.getBalanceCents() + shareCents);
            shares.add(MoneyUtil.format(shareCents));
        }

        from.setBalanceCents(from.getBalanceCents() - totalCents);
        return shares;
    }

    @Override
    public String totalHoldings() {
        long sumCents = 0;
        for (Account a : store.all()) {
            sumCents += a.getBalanceCents();
        }
        return MoneyUtil.format(sumCents);
    }
}

